INSERT INTO public.findit_challenges(challenge_id,name,description,active) VALUES ('C046','A Shadow Creature','Arrange objects and a light to cast the shadow of an imaginary creature.',true),('C047','A Household Rainbow','Arrange everyday objects into a rainbow of colours.',true),('C048','A Floating Object','Use a hidden support or clever camera angle to make an object appear to float.',true),('C049','A Picture Made of Things','Arrange household objects into a recognisable picture, such as a boat or flower.',true),('C050','Spell HOME With Objects','Arrange everyday items to form the four letters H, O, M, E, then photograph the word.',true),('C051','A Bridge Between Two Things','Build a small bridge between two objects using lightweight household items.',true),('C052','A Weather Scene Indoors','Use household objects to create sunshine, rain or snow without using real water.',true),('C053','One Thing, Two Halves','Line up halves of two different objects to make one surprising new object.',true),('C054','A Homemade Invention','Combine everyday objects into a pretend gadget and photograph what it might do.',true) ON CONFLICT (challenge_id) DO NOTHING;